package com.ayindebuild.app.services\n\nimport android.content.Context\nimport kotlinx.coroutines.*\nimport java.io.BufferedReader\nimport java.io.InputStreamReader\n\nclass BuildService(private val context: Context) {\n    private val scope = CoroutineScope(Dispatchers.Main + Job())\n\n    fun compile(command: String, onOutput: (String) -> Unit) {\n        scope.launch(Dispatchers.IO) {\n            try {\n                val process = Runtime.getRuntime().exec(arrayOf(\"sh\", \"-c\", command))\n                val reader = BufferedReader(InputStreamReader(process.inputStream))\n                val output = StringBuilder()\n                var line: String? = reader.readLine()\n\n                while (line != null) {\n                    output.append(line).append(\"\\n\")\n                    withContext(Dispatchers.Main) {\n                        onOutput(output.toString())\n                    }\n                    line = reader.readLine()\n                }\n\n                process.waitFor()\n                reader.close()\n            } catch (e: Exception) {\n                withContext(Dispatchers.Main) {\n                    onOutput(\"Error: ${e.message}\")\n                }\n            }\n        }\n    }\n\n    fun run(command: String, onOutput: (String) -> Unit) {\n        compile(command, onOutput)\n    }\n\n    fun destroy() {\n        scope.cancel()\n    }\n}\n